/* Alonehorror Map Studio - dependency-free offline editor.
 *
 * Mirrors the Python SDK: same .jmap byte layout, same tile id ranges,
 * same 16x16 grid.  The editor bundle (bundle.js) is generated by
 * tools/build_project.py and makes the page work from file:// with no server.
 */
(() => {
  'use strict';

  const C = {
    TILE_SIZE: 16,
    EMPTY: 0,
    TILE_MAX: 4095,
    ITEM_BASE: 4096,
    ENEMY_BASE: 4352,
    TRIGGER_BASE: 4608,
    SPAWN: 4608,
    EXIT: 4609,
    KIND_ITEM: 0,
    KIND_ENEMY: 1,
    KIND_TRIGGER: 2,
    KIND_DECOR: 3,
    SOLID: 1, WATER: 2, PIT: 4, HAZARD: 8, DOOR: 16, LADDER: 32, TRIGGER: 64,
    LOCKED: 0x10,
    FACING_MASK: 0x03,
  };

  const $ = (id) => document.getElementById(id);
  const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
  const escapeHtml = (s) => String(s).replace(/[&<>"']/g, (c) => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
  }[c]));

  const COLLISION_NAMES = [
    [C.SOLID, 'solid'], [C.WATER, 'water'], [C.PIT, 'pit'],
    [C.HAZARD, 'hazard'], [C.DOOR, 'door'], [C.LADDER, 'ladder'],
    [C.TRIGGER, 'trigger'],
  ];
  const collisionName = (v) => {
    const out = COLLISION_NAMES.filter(([bit]) => v & bit).map(([, n]) => n);
    return out.length ? out.join('+') : 'walkable';
  };
  const triggerStyle = (id) => {
    const defaults = {
      [C.SPAWN]: { name: 'player_spawn', color: [235, 32, 32] },
      [C.EXIT]: { name: 'level_exit', color: [32, 220, 64] },
      4610: { name: 'level_start', color: [255, 190, 32] },
      4611: { name: 'cutscene', color: [64, 140, 255] },
      4612: { name: 'talk_jonathan', color: [255, 120, 200] },
      4613: { name: 'door_crowbar', color: [200, 40, 40] },
    };
    const types = (state.objectTypes || state.manifest?.objectTypes)?.triggers || [];
    return types.find((t) => t.id === id) || defaults[id] || { name: 'trigger', color: [255, 255, 255] };
  };
  const objectStyle = (obj) => {
    if (obj.kind === C.KIND_TRIGGER) return triggerStyle(obj.type);
    const group = obj.kind === C.KIND_ENEMY ? 'enemies'
      : obj.kind === C.KIND_ITEM ? 'items' : 'triggers';
    const list = (state.objectTypes || state.manifest?.objectTypes)?.[group] || [];
    return list.find((t) => t.id === obj.type) || { name: 'object', color: [200, 200, 200] };
  };

  // ---------------------------------------------------------------------
  // .jmap codec (big endian, identical to sdk/jmap.py)
  // ---------------------------------------------------------------------
  const { encodeJMap, decodeJMap, fnv1a, base64ToBytes } = window.JMapCodec;

  // ---------------------------------------------------------------------
  // Global state
  // ---------------------------------------------------------------------
  const state = {
    project: null, manifest: null, atlasImage: null, atlasCanvas: null, atlasCtx: null,
    tileMeta: {}, hashToId: new Map(), nextTileId: 1,
    maps: {}, mapOrder: [], activeName: null, active: null,
    layer: 'terrain', tool: 'brush', selectedTile: 1,
    selectedObject: null, selectedObj: -1, objectFilter: 'triggers', objectTypes: null,
    collisionBrush: C.SOLID,
    zoom: 2, camX: 0, camY: 0, hover: null,
    paletteFilter: 'used', paletteSearch: '', paletteItems: [],
    sources: {}, panning: false, spaceDown: false, painting: false,
    lastPaint: null, panStart: null, selectedAnomaly: -1,
    showGrid: true, showObjects: true, showCollision: false,
    showAnomalies: true, showSource: false,
    dirtyCheck: false,
  };

  const els = {};
  ['mapCanvas', 'paletteCanvas', 'mapTabs', 'layerButtons', 'toolButtons',
   'collisionTools', 'collisionBrush', 'toggleGrid', 'toggleObjects',
   'toggleCollision', 'toggleAnomalies', 'toggleSource', 'paletteTitle',
   'paletteCount', 'paletteFilters', 'paletteSearch', 'paletteScroll',
   'tileInfo', 'inspector', 'dirtyBadge', 'anomalyCount', 'anomalyList',
   'btnAcceptAll', 'btnNextAnomaly', 'warningList', 'objectTabs',
   'objectList', 'objectFilterCount', 'statusCell', 'statusTile',
   'statusCollision', 'statusZoom', 'statusMap', 'toast', 'emptyState',
   'offsetX', 'offsetY', 'btnRender', 'btnExportMap', 'btnExportProject',
   'btnImportMap', 'btnImportTileset', 'btnReplaceSource', 'btnExportTileset',
   'btnCleanGarbage', 'btnReslice', 'fileMap', 'fileTileset', 'fileSource', 'viewport'
  ].forEach((id) => { els[id] = $(id); });

  // ---------------------------------------------------------------------
  // Bundle loading
  // ---------------------------------------------------------------------
  async function loadImage(src) {
    return new Promise((resolve, reject) => {
      const img = new Image();
      img.onload = () => resolve(img);
      img.onerror = () => reject(new Error('image failed to load'));
      img.src = src;
    });
  }

  async function initBundle(bundle) {
    state.project = bundle.project;
    state.manifest = bundle.tileset;
    const objectTypes = bundle.objectTypes
      || (state.project && state.project.objectTypes) || null;
    if (objectTypes) {
      state.objectTypes = objectTypes;
      state.manifest.objectTypes = objectTypes;
    }
    state.atlasImage = await loadImage(bundle.atlas);
    buildAtlasCanvas(state.atlasImage);
    indexTiles();

    for (const [key, src] of Object.entries(bundle.sources || {})) {
      try { state.sources[key] = await loadImage(src); } catch (e) { /* ignore */ }
    }

    for (const pm of bundle.project.maps) {
      try {
        const data = decodeJMap(base64ToBytes(bundle.maps[pm.name]));
        state.maps[pm.name] = {
          name: pm.name, data, project: pm,
          anomalies: JSON.parse(JSON.stringify(pm.anomalies || [])),
          warnings: (pm.warnings || []).slice(),
          offset: (pm.offset || [0, 0]).slice(),
          sourceKey: pm.name, sourcePath: pm.source,
          history: [], redo: [], dirty: false,
          selectedAnomaly: -1, cam: null,
        };
        state.mapOrder.push(pm.name);
      } catch (e) {
        console.error('failed to decode map', pm.name, e);
        toast('Could not decode ' + pm.name + ': ' + e.message, true);
      }
    }
    if (!state.mapOrder.length) {
      els.emptyState.classList.remove('hidden');
      return;
    }
    buildMapTabs();
    selectMap(state.mapOrder[0]);
    renderObjectPalette();
  }

  function buildAtlasCanvas(image) {
    const columns = state.manifest.columns || 64;
    const size = state.manifest.tileSize || 16;
    let rows = Math.max(state.manifest.rows || 1,
      Math.ceil((state.manifest.tileCount || 1) / columns));
    if (image) {
      rows = Math.max(rows, Math.ceil(image.height / size));
    }
    const canvas = document.createElement('canvas');
    canvas.width = columns * size;
    canvas.height = rows * size;
    const ctx = canvas.getContext('2d');
    ctx.imageSmoothingEnabled = false;
    if (image) ctx.drawImage(image, 0, 0);
    state.atlasCanvas = canvas;
    state.atlasCtx = ctx;
  }

  function indexTiles() {
    state.tileMeta = {};
    state.hashToId = new Map();
    state.tileMeta[0] = {
      id: 0, name: 'empty', kind: 'empty', collision: C.SOLID,
      shared: false, maps: {}, count: 0, fastHash: '',
    };
    let maxId = 0;
    for (const tile of state.manifest.tiles || []) {
      state.tileMeta[tile.id] = tile;
      if (tile.fastHash) state.hashToId.set(tile.fastHash, tile.id);
      maxId = Math.max(maxId, tile.id);
    }
    state.nextTileId = maxId + 1;
  }

  // ---------------------------------------------------------------------
  // Tabs / map selection
  // ---------------------------------------------------------------------
  function buildMapTabs() {
    els.mapTabs.innerHTML = state.mapOrder.map((name) => {
      const s = state.maps[name];
      const anomalies = s.anomalies.length;
      const active = name === state.activeName ? ' active' : '';
      return `<button data-map="${escapeHtml(name)}" class="${active.trim()}">
        ${escapeHtml(name)}
        <span class="tab-meta">${s.data.width}x${s.data.height}${anomalies ? ' !' + anomalies : ''}</span>
      </button>`;
    }).join('');
  }

  function updateTabs() {
    buildMapTabs();
  }

  function selectMap(name) {
    if (!state.maps[name]) return;
    state.activeName = name;
    state.active = state.maps[name];
    const s = state.active;
    if (!s.cam) {
      s.cam = { x: 0, y: 0, zoom: null };
    }
    buildMapTabs();
    els.offsetX.value = s.offset[0];
    els.offsetY.value = s.offset[1];
    els.dirtyBadge.textContent = s.dirty ? 'unsaved' : 'clean';
    els.dirtyBadge.className = 'badge ' + (s.dirty ? 'dirty' : 'muted');
    els.emptyState.classList.add('hidden');
    if (!s.cam.zoom) fitView();
    state.zoom = s.cam.zoom;
    state.camX = s.cam.x;
    state.camY = s.cam.y;
    state.selectedAnomaly = s.selectedAnomaly;
    state.selectedObj = -1;
    renderPalette();
    renderAnomalies();
    renderWarnings();
    renderInspector();
    updateStatus();
    render();
  }

  function fitView() {
    const s = state.active;
    if (!s) return;
    const cw = els.mapCanvas.clientWidth || 800;
    const ch = (els.mapCanvas.clientHeight || 600) - 24;
    const z = Math.min(cw / (s.data.width * 16), ch / (s.data.height * 16)) * 0.94;
    const zoom = clamp(Math.round(z * 4) / 4, 0.5, 4);
    const camX = (s.data.width * 16 - cw / zoom) / 2;
    const camY = (s.data.height * 16 - ch / zoom) / 2;
    s.cam = { x: camX, y: camY, zoom };
    state.zoom = zoom;
    state.camX = camX;
    state.camY = camY;
    els.statusZoom.textContent = 'zoom ' + zoom + 'x';
  }

  // ---------------------------------------------------------------------
  // Palette
  // ---------------------------------------------------------------------
  function usedCounts(s) {
    const counts = new Map();
    for (const id of s.data.terrain) counts.set(id, (counts.get(id) || 0) + 1);
    return counts;
  }

  function paletteList() {
    if (!state.active || !state.manifest) return [];
    const s = state.active;
    const used = usedCounts(s);
    const all = [];
    const maxId = Math.max(0, ...Object.keys(state.tileMeta).map(Number));
    for (let id = 1; id <= maxId; id++) {
      const meta = state.tileMeta[id];
      if (!meta) continue;
      all.push({ id, meta, used: used.get(id) || 0 });
    }
    let list = all;
    if (state.paletteFilter === 'used') list = all.filter((t) => t.used > 0);
    else if (state.paletteFilter === 'shared') list = all.filter((t) => t.meta.shared);
    else if (state.paletteFilter === 'unique') list = all.filter((t) => t.used === 1 && !t.meta.shared);
    const q = state.paletteSearch.trim().toLowerCase();
    if (q) {
      list = list.filter((t) =>
        String(t.id).includes(q) ||
        (t.meta.name || '').toLowerCase().includes(q) ||
        (t.meta.kind || '').toLowerCase().includes(q));
    }
    return list;
  }

  function renderPalette() {
    if (!state.active || !state.manifest) return;
    const list = paletteList();
    state.paletteItems = list;
    const canvas = els.paletteCanvas;
    const ctx = canvas.getContext('2d');
    const cell = 34, cols = 8, pad = 1;
    const rows = Math.max(1, Math.ceil(list.length / cols));
    const width = cols * cell;
    canvas.width = width;
    canvas.height = rows * cell;
    ctx.imageSmoothingEnabled = false;
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = '#0b0f13';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    const size = state.manifest.tileSize || 16;
    const columns = state.manifest.columns || 64;
    list.forEach((item, index) => {
      const x = (index % cols) * cell;
      const y = Math.floor(index / cols) * cell;
      ctx.fillStyle = item.id === state.selectedTile ? '#5b3d16' : '#11161c';
      ctx.fillRect(x + pad, y + pad, cell - 2, cell - 2);
      if (item.id !== C.EMPTY && state.atlasCanvas) {
        const sx = (item.id % columns) * size;
        const sy = Math.floor(item.id / columns) * size;
        ctx.drawImage(state.atlasCanvas, sx, sy, size, size,
          x + 1, y + 1, cell - 2, cell - 2);
      } else if (item.id === C.EMPTY) {
        ctx.fillStyle = '#07090b';
        ctx.fillRect(x + 1, y + 1, cell - 2, cell - 2);
      }
      if (item.id === state.selectedTile) {
        ctx.strokeStyle = '#ffb300';
        ctx.lineWidth = 2;
        ctx.strokeRect(x + 1, y + 1, cell - 2, cell - 2);
      }
    });
    els.paletteCount.textContent = list.length + ' tiles';
    els.paletteTitle.textContent = state.layer === 'collision'
      ? 'Collision brush' : 'Terrain palette';
    renderTileInfo();
  }

  function hitPalette(ev) {
    const rect = els.paletteCanvas.getBoundingClientRect();
    const x = ev.clientX - rect.left;
    const y = ev.clientY - rect.top;
    const cell = 34, cols = 8;
    const index = Math.floor(y / cell) * cols + Math.floor(x / cell);
    return state.paletteItems[index] || null;
  }

  function renderTileInfo() {
    const meta = state.tileMeta[state.selectedTile];
    if (!meta) { els.tileInfo.textContent = 'No tile selected.'; return; }
    const maps = Object.keys(meta.maps || {});
    const collision = collisionName(meta.collision || 0);
    els.tileInfo.innerHTML =
      `<b>tile ${meta.id}</b> &middot; ${escapeHtml(meta.kind || 'unknown')} &middot; ${collision}` +
      `${meta.shared ? ' &middot; <span style="color:#ffb300">shared</span>' : ''}<br>` +
      `${escapeHtml(meta.name || '')} ${maps.length ? '&middot; ' + escapeHtml(maps.join(', ')) : ''}`;
  }

  // ---------------------------------------------------------------------
  // Object palette
  // ---------------------------------------------------------------------
  function renderObjectPalette() {
    if (!state.manifest) return;
    const group = state.objectFilter;
    const list = (state.objectTypes || state.manifest.objectTypes)?.[group] || [];
    els.objectFilterCount.textContent = list.length;
    els.objectList.innerHTML = list.map((t) => {
      const color = `rgb(${(t.color || [200, 200, 200]).join(',')})`;
      const kind = group === 'triggers' ? C.KIND_TRIGGER
        : group === 'enemies' ? C.KIND_ENEMY : C.KIND_ITEM;
      const active = state.selectedObject
        && state.selectedObject.kind === kind
        && state.selectedObject.type === t.id ? ' active' : '';
      return `<div class="object-item${active}" data-kind="${kind}" data-type="${t.id}">
        <span class="swatch" style="background:${color}"></span>
        <span class="name">${escapeHtml(t.name)}</span>
        <span class="id">${t.id}</span>
      </div>`;
    }).join('');
    if (!state.selectedObject && list.length) {
      const kind = group === 'triggers' ? C.KIND_TRIGGER
        : group === 'enemies' ? C.KIND_ENEMY : C.KIND_ITEM;
      state.selectedObject = { kind, type: list[0].id };
      renderObjectPalette();
    }
  }

  // ---------------------------------------------------------------------
  // Rendering
  // ---------------------------------------------------------------------
  function resizeCanvas() {
    const canvas = els.mapCanvas;
    const dpr = window.devicePixelRatio || 1;
    const w = canvas.clientWidth || els.viewport.clientWidth;
    const h = canvas.clientHeight || els.viewport.clientHeight;
    canvas.width = Math.max(1, Math.round(w * dpr));
    canvas.height = Math.max(1, Math.round(h * dpr));
    render();
  }

  function render() {
    const canvas = els.mapCanvas;
    const ctx = canvas.getContext('2d');
    const dpr = window.devicePixelRatio || 1;
    const W = canvas.width / dpr, H = canvas.height / dpr;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.imageSmoothingEnabled = false;
    ctx.fillStyle = '#080b0e';
    ctx.fillRect(0, 0, W, H);
    const s = state.active;
    if (!s || !state.atlasCanvas) return;
    const zoom = state.zoom, size = 16, tilePx = size * zoom;
    const camX = state.camX, camY = state.camY;
    const startX = clamp(Math.floor(camX / size) - 1, 0, s.data.width - 1);
    const startY = clamp(Math.floor(camY / size) - 1, 0, s.data.height - 1);
    const endX = clamp(Math.ceil((camX + W / zoom) / size) + 1, 0, s.data.width);
    const endY = clamp(Math.ceil((camY + H / zoom) / size) + 1, 0, s.data.height);
    const columns = state.manifest.columns || 64;

    for (let cy = startY; cy < endY; cy++) {
      for (let cx = startX; cx < endX; cx++) {
        const id = s.data.terrain[cy * s.data.width + cx];
        if (!id) continue;
        const sx = (id % columns) * size;
        const sy = Math.floor(id / columns) * size;
        if (sx + size > state.atlasCanvas.width || sy + size > state.atlasCanvas.height) continue;
        ctx.drawImage(state.atlasCanvas, sx, sy, size, size,
          (cx * size - camX) * zoom, (cy * size - camY) * zoom, tilePx, tilePx);
      }
    }

    if (state.showSource) {
      const img = state.sources[s.sourceKey];
      if (img) {
        ctx.save();
        ctx.globalAlpha = 0.42;
        ctx.drawImage(img,
          (-s.offset[0] - camX) * zoom, (-s.offset[1] - camY) * zoom,
          img.width * zoom, img.height * zoom);
        ctx.restore();
      }
    }

    if (state.showCollision) {
      for (let cy = startY; cy < endY; cy++) {
        for (let cx = startX; cx < endX; cx++) {
          const v = s.data.collision[cy * s.data.width + cx];
          if (!v) continue;
          let color = 'rgba(255,64,48,0.30)';
          if (v & C.WATER) color = 'rgba(40,110,255,0.34)';
          else if (v & C.HAZARD) color = 'rgba(255,120,20,0.38)';
          else if (v & C.PIT) color = 'rgba(140,20,180,0.38)';
          ctx.fillStyle = color;
          ctx.fillRect((cx * size - camX) * zoom, (cy * size - camY) * zoom, tilePx, tilePx);
        }
      }
    }

    if (state.showAnomalies && s.anomalies.length) {
      s.anomalies.forEach((a, index) => {
        const x = (a.x * size - camX) * zoom;
        const y = (a.y * size - camY) * zoom;
        const w = (a.w || 1) * tilePx, hh = (a.h || 1) * tilePx;
        ctx.fillStyle = index === state.selectedAnomaly
          ? 'rgba(255,179,0,0.22)' : 'rgba(255,190,40,0.10)';
        ctx.fillRect(x, y, w, hh);
        ctx.strokeStyle = index === state.selectedAnomaly ? '#ffcc44' : 'rgba(255,200,60,0.55)';
        ctx.lineWidth = index === state.selectedAnomaly ? 2 : 1;
        ctx.setLineDash([5, 4]);
        ctx.strokeRect(x + 0.5, y + 0.5, w - 1, hh - 1);
        ctx.setLineDash([]);
      });
    }

    if (state.showObjects) {
      for (const obj of s.data.objects) drawObject(ctx, obj, camX, camY, zoom);
    }

    if (state.showGrid && zoom >= 0.9) {
      const x0 = (startX * size - camX) * zoom;
      const y0 = (startY * size - camY) * zoom;
      ctx.strokeStyle = 'rgba(180,210,255,0.09)';
      ctx.lineWidth = 1;
      ctx.beginPath();
      for (let cx = startX; cx <= endX; cx++) {
        const x = Math.round((cx * size - camX) * zoom) + 0.5;
        ctx.moveTo(x, y0); ctx.lineTo(x, y0 + (endY - startY) * tilePx);
      }
      for (let cy = startY; cy <= endY; cy++) {
        const y = Math.round((cy * size - camY) * zoom) + 0.5;
        ctx.moveTo(x0, y); ctx.lineTo(x0 + (endX - startX) * tilePx, y);
      }
      ctx.stroke();
      if (zoom >= 1.5) {
        ctx.strokeStyle = 'rgba(180,210,255,0.16)';
        ctx.beginPath();
        for (let cx = startX; cx <= endX; cx += 4) {
          const x = Math.round((cx * size - camX) * zoom) + 0.5;
          ctx.moveTo(x, y0); ctx.lineTo(x, y0 + (endY - startY) * tilePx);
        }
        for (let cy = startY; cy <= endY; cy += 4) {
          const y = Math.round((cy * size - camY) * zoom) + 0.5;
          ctx.moveTo(x0, y); ctx.lineTo(x0 + (endX - startX) * tilePx, y);
        }
        ctx.stroke();
      }
    }

    if (state.hover) {
      const hx = (state.hover.x * size - camX) * zoom;
      const hy = (state.hover.y * size - camY) * zoom;
      ctx.strokeStyle = state.layer === 'objects' ? '#ff8a80'
        : state.layer === 'collision' ? '#58a6ff' : '#ffffff';
      ctx.lineWidth = 1.5;
      ctx.strokeRect(hx + 0.5, hy + 0.5, tilePx - 1, tilePx - 1);
    }
  }

  function drawObject(ctx, obj, camX, camY, zoom) {
    const size = 16 * zoom;
    const x = (obj.x * 16 - camX) * zoom;
    const y = (obj.y * 16 - camY) * zoom;
    const cx = x + size / 2, cy = y + size / 2;
    const style = objectStyle(obj);
    const color = `rgb(${(style.color || [210, 210, 210]).join(',')})`;
    ctx.lineWidth = Math.max(1, zoom * 0.8);
    if (obj.kind === C.KIND_TRIGGER) {
      ctx.fillStyle = color;
      ctx.strokeStyle = '#ffffff';
      ctx.fillRect(x + size * 0.15, y + size * 0.15, size * 0.7, size * 0.7);
      ctx.strokeRect(x + size * 0.15, y + size * 0.15, size * 0.7, size * 0.7);
      ctx.fillStyle = '#102018';
      if (obj.type === C.SPAWN) {
        ctx.fillRect(x + size * 0.32, y + size * 0.4, size * 0.36, size * 0.22);
        ctx.fillRect(x + size * 0.4, y + size * 0.28, size * 0.2, size * 0.14);
      } else {
        ctx.fillRect(x + size * 0.28, y + size * 0.46, size * 0.44, size * 0.09);
        ctx.fillRect(x + size * 0.46, y + size * 0.28, size * 0.09, size * 0.44);
      }
    } else if (obj.kind === C.KIND_ITEM) {
      ctx.fillStyle = color;
      ctx.strokeStyle = '#161616';
      ctx.beginPath();
      ctx.moveTo(cx, y + size * 0.18);
      ctx.lineTo(x + size * 0.82, cy);
      ctx.lineTo(cx, y + size * 0.82);
      ctx.lineTo(x + size * 0.18, cy);
      ctx.closePath();
      ctx.fill(); ctx.stroke();
    } else if (obj.kind === C.KIND_ENEMY) {
      ctx.fillStyle = (obj.flags & C.LOCKED) ? '#f0a23c' : color;
      ctx.strokeStyle = '#161616';
      ctx.beginPath();
      ctx.arc(cx, cy, size * 0.31, 0, Math.PI * 2);
      ctx.fill(); ctx.stroke();
      if (obj.flags & C.LOCKED) {
        ctx.strokeStyle = '#ffcc44';
        ctx.setLineDash([3, 2]);
        ctx.strokeRect(x + 1, y + 1, size - 2, size - 2);
        ctx.setLineDash([]);
      }
    } else {
      ctx.strokeStyle = color;
      ctx.strokeRect(x + size * 0.22, y + size * 0.22, size * 0.56, size * 0.56);
    }
  }

  // ---------------------------------------------------------------------
  // Inspector / status / warnings / anomalies
  // ---------------------------------------------------------------------
  function updateStatus() {
    const s = state.active;
    if (!s) return;
    els.statusMap.textContent = `${s.name} · ${s.data.width}x${s.data.height} · offset ${s.offset[0]},${s.offset[1]}`;
    els.statusZoom.textContent = 'zoom ' + state.zoom + 'x';
    if (state.hover) {
      const { x, y } = state.hover;
      const inside = x >= 0 && y >= 0 && x < s.data.width && y < s.data.height;
      els.statusCell.textContent = inside ? `cell ${x},${y}` : '-';
      if (inside) {
        const idx = y * s.data.width + x;
        els.statusTile.textContent = 'tile ' + s.data.terrain[idx];
        els.statusCollision.textContent = collisionName(s.data.collision[idx]);
      } else {
        els.statusTile.textContent = 'tile -';
        els.statusCollision.textContent = 'collision -';
      }
    }
  }

  function renderInspector() {
    const s = state.active;
    if (!s) { els.inspector.innerHTML = ''; return; }
    const meta = state.tileMeta[state.selectedTile] || state.tileMeta[0];
    const rows = [];
    rows.push(['map', `${s.name} · ${s.data.width}x${s.data.height}`]);
    rows.push(['grid offset', `${s.offset[0]}, ${s.offset[1]}`]);
    rows.push(['cells', s.data.width * s.data.height]);
    rows.push(['objects', s.data.objects.length]);
    rows.push(['anomalies', s.anomalies.length]);
    if (state.hover && state.hover.x >= 0 && state.hover.y >= 0
        && state.hover.x < s.data.width && state.hover.y < s.data.height) {
      const x = state.hover.x, y = state.hover.y;
      const idx = y * s.data.width + x;
      rows.push(['hover', `${x}, ${y}`]);
      rows.push(['tile under cursor', String(s.data.terrain[idx])]);
      rows.push(['collision', collisionName(s.data.collision[idx])]);
      const objs = s.data.objects.filter((o) => o.x === x && o.y === y);
      if (objs.length) {
        rows.push(['objects here', objs.map((o) =>
          `${o.kind === 2 ? 'trigger' : o.kind === 1 ? 'enemy' : 'item'}:${o.type}`).join(', ')]);
      }
    }
    rows.push(['selected tile', `${meta.id} · ${meta.kind || 'unknown'}`]);
    rows.push(['tile collision', collisionName(meta.collision || 0)]);
    rows.push(['tile usage', `${meta.count || 0} cell(s), ${Object.keys(meta.maps || {}).length} map(s)`]);
    if (state.selectedObject) {
      const style = objectStyle({ kind: state.selectedObject.kind, type: state.selectedObject.type });
      rows.push(['object brush', `${style.name} (${state.selectedObject.type})`]);
    }
    let html = rows.map(([k, v]) =>
      `<div class="row"><span>${escapeHtml(k)}</span><span>${escapeHtml(v)}</span></div>`).join('');
    const oi = state.selectedObj;
    if (oi >= 0 && oi < s.data.objects.length) {
      const o = s.data.objects[oi];
      const style = objectStyle(o);
      const kindName = o.kind === C.KIND_TRIGGER ? 'trigger'
        : o.kind === C.KIND_ENEMY ? 'enemy' : 'item';
      html += `<div class="obj-editor">
        <div class="obj-head"><b>selected ${escapeHtml(kindName)}</b>
          <span>${escapeHtml(style.name)} #${o.type}</span>
          <button id="objDelete" class="small">Delete</button></div>
        <div class="obj-grid">
          <label>type <input id="objType" type="number" min="0" max="65535" value="${o.type}"></label>
          <label>x <input id="objX" type="number" min="0" value="${o.x}"></label>
          <label>y <input id="objY" type="number" min="0" value="${o.y}"></label>
          <label>param <input id="objParam" type="number" min="0" max="65535" value="${o.param}"></label>
          <label>flags <input id="objFlags" type="number" min="0" max="255" value="${o.flags}"></label>
        </div>
      </div>`;
    }
    els.inspector.innerHTML = html;
  }

  function dynamicWarnings(s) {
    const out = [];
    const triggers = s.data.objects.filter((o) => o.kind === C.KIND_TRIGGER);
    const hasSpawn = triggers.some((o) => o.type === C.SPAWN);
    const hasExit = triggers.some((o) => o.type === C.EXIT || o.type === 4612 || o.type === 4613);
    out.push({
      text: hasSpawn ? 'Player spawn placed.' : 'Player spawn marker (red) is missing. Place trigger #4608.',
      solved: hasSpawn,
    });
    out.push({
      text: hasExit ? 'Chapter ending placed.' : 'Chapter ending is missing (exit, Jonathan or crowbar door).',
      solved: hasExit,
    });
    if (s.anomalies.length) {
      out.push({ text: `${s.anomalies.length} anomaly cell(s) need review (yellow boxes).`, solved: false });
    }
    const tempCells = s.data.terrain.filter((id) => state.tileMeta[id]?.temp).length;
    if (tempCells) {
      out.push({ text: `${tempCells} cell(s) still use the temporary broken texture. Accept/dismiss their anomaly or paint over them, then run Clean garbage.`, solved: false });
    }
    const locked = s.data.objects.filter((o) => o.flags & C.LOCKED).length;
    if (locked) out.push({ text: `${locked} auto-suggested object(s) are locked; accept or adjust them.`, solved: false });
    for (const w of s.warnings) {
      if (/spawn marker|exit marker|broken_temp/i.test(w)) continue;
      out.push({ text: w, solved: false });
    }
    return out;
  }

  function renderWarnings() {
    const s = state.active;
    if (!s) return;
    els.warningList.innerHTML = dynamicWarnings(s).map((w) =>
      `<div class="warning${w.solved ? ' solved' : ''}">${w.solved ? '&#10003; ' : ''}${escapeHtml(w.text)}</div>`
    ).join('') || '<div class="warning solved">No warnings.</div>';
  }

  function renderAnomalies() {
    const s = state.active;
    if (!s) return;
    els.anomalyCount.textContent = s.anomalies.length;
    els.anomalyCount.className = 'badge' + (s.anomalies.length ? ' warn' : ' muted');
    els.anomalyList.innerHTML = s.anomalies.map((a, i) => {
      const active = i === s.selectedAnomaly ? ' active' : '';
      return `<div class="anomaly${active}" data-anomaly="${i}">
        <div class="head"><span>#${i + 1} at ${a.x},${a.y} (${a.w}x${a.h})</span><span>${Math.round((a.confidence || 0) * 100)}%</span></div>
        <div class="meta">${a.reason || 'sprite'} &middot; suggested <b>${a.suggestion || '?'}</b>${a.temp ? ' &middot; temp texture' : ''}${a.sourceBBox ? ' &middot; source ' + a.sourceBBox.join(',') : ''}</div>
        <div class="actions">
          <button data-act="focus" data-index="${i}" class="small">Focus</button>
          <button data-act="accept" data-index="${i}" class="small">Accept</button>
          <button data-act="dismiss" data-index="${i}" class="small">Dismiss</button>
        </div>
      </div>`;
    }).join('') || '<div class="tile-info">No anomalies in this map.</div>';
    updateTabs();
    renderWarnings();
  }

  // ---------------------------------------------------------------------
  // Editing helpers
  // ---------------------------------------------------------------------
  function markDirty() {
    const s = state.active;
    if (!s) return;
    s.dirty = true;
    els.dirtyBadge.textContent = 'unsaved';
    els.dirtyBadge.className = 'badge dirty';
    updateTabs();
  }

  function snapshot(s) {
    return {
      terrain: s.data.terrain.slice(),
      collision: s.data.collision.slice(),
      objects: s.data.objects.map((o) => ({ ...o })),
      anomalies: JSON.parse(JSON.stringify(s.anomalies)),
      warnings: s.warnings.slice(),
    };
  }

  function pushHistory() {
    const s = state.active;
    if (!s) return;
    s.history.push(snapshot(s));
    if (s.history.length > 60) s.history.shift();
    s.redo = [];
  }

  function restore(s, snap) {
    s.data.terrain = snap.terrain.slice();
    s.data.collision = snap.collision.slice();
    s.data.objects = snap.objects.map((o) => ({ ...o }));
    s.anomalies = JSON.parse(JSON.stringify(snap.anomalies || []));
    s.warnings = (snap.warnings || []).slice();
    s.selectedAnomaly = -1;
    state.selectedAnomaly = -1;
    markDirty();
    render();
    renderInspector();
    renderAnomalies();
    renderWarnings();
  }

  function undo() {
    const s = state.active;
    if (!s || !s.history.length) return;
    s.redo.push(snapshot(s));
    restore(s, s.history.pop());
    toast('Undo');
  }

  function redo() {
    const s = state.active;
    if (!s || !s.redo.length) return;
    s.history.push(snapshot(s));
    restore(s, s.redo.pop());
    toast('Redo');
  }

  function restoreAnomalyTerrain(s, a) {
    let changed = false;
    for (const fix of (a.fixTiles || [])) {
      const [x, y, tile] = fix;
      if (x < 0 || y < 0 || x >= s.data.width || y >= s.data.height
          || (tile !== C.EMPTY && !state.tileMeta[tile])) continue;
      const idx = y * s.data.width + x;
      if (s.data.terrain[idx] === tile) continue;
      s.data.terrain[idx] = tile;
      s.data.collision[idx] = tile === C.EMPTY ? 0 : (state.tileMeta[tile].collision || 0);
      changed = true;
    }
    return changed;
  }

  function pruneTempWarnings(s) {
    const tempCells = s.data.terrain.filter((id) => state.tileMeta[id]?.temp).length;
    if (!tempCells) s.warnings = s.warnings.filter((w) => !/broken_temp/i.test(w));
  }

  function clearAnomalyAtCell(s, cx, cy) {
    const idx = s.anomalies.findIndex((a) => {
      if (Array.isArray(a.cells) && a.cells.length) {
        return a.cells.some(([x, y]) => x === cx && y === cy);
      }
      return cx >= a.x && cy >= a.y && cx < a.x + (a.w || 1) && cy < a.y + (a.h || 1);
    });
    if (idx < 0) return false;
    restoreAnomalyTerrain(s, s.anomalies[idx]);
    s.anomalies.splice(idx, 1);
    s.selectedAnomaly = -1;
    state.selectedAnomaly = -1;
    pruneTempWarnings(s);
    return true;
  }

  function applyTerrain(cx, cy, erase) {
    const s = state.active;
    if (cx < 0 || cy < 0 || cx >= s.data.width || cy >= s.data.height) return;
    clearAnomalyAtCell(s, cx, cy);
    const idx = cy * s.data.width + cx;
    const id = erase ? C.EMPTY : state.selectedTile;
    if (s.data.terrain[idx] !== id) s.data.terrain[idx] = id;
  }

  function applyCollision(cx, cy, erase) {
    const s = state.active;
    if (cx < 0 || cy < 0 || cx >= s.data.width || cy >= s.data.height) return;
    const idx = cy * s.data.width + cx;
    s.data.collision[idx] = erase ? 0 : state.collisionBrush;
  }

  function applyAt(cx, cy, erase) {
    if (!state.active) return;
    if (state.layer === 'terrain') applyTerrain(cx, cy, erase);
    else if (state.layer === 'collision') applyCollision(cx, cy, erase);
  }

  function floodFill(cx, cy, erase) {
    const s = state.active;
    if (cx < 0 || cy < 0 || cx >= s.data.width || cy >= s.data.height) return;
    if (state.layer === 'objects') return;
    const arr = state.layer === 'collision' ? s.data.collision : s.data.terrain;
    const width = s.data.width, height = s.data.height;
    const target = arr[cy * width + cx];
    const value = state.layer === 'collision'
      ? (erase ? 0 : state.collisionBrush)
      : (erase ? C.EMPTY : state.selectedTile);
    if (target === value) return;
    const stack = [[cx, cy]];
    let guard = width * height + 10;
    while (stack.length && guard-- > 0) {
      const [x, y] = stack.pop();
      if (x < 0 || y < 0 || x >= width || y >= height) continue;
      const i = y * width + x;
      if (arr[i] !== target) continue;
      arr[i] = value;
      stack.push([x + 1, y], [x - 1, y], [x, y + 1], [x, y - 1]);
    }
  }

  function lineCells(x0, y0, x1, y1) {
    const out = [];
    let dx = Math.abs(x1 - x0), dy = Math.abs(y1 - y0);
    let sx = x0 < x1 ? 1 : -1, sy = y0 < y1 ? 1 : -1;
    let err = dx - dy;
    while (true) {
      out.push([x0, y0]);
      if (x0 === x1 && y0 === y1) break;
      const e2 = 2 * err;
      if (e2 > -dy) { err -= dy; x0 += sx; }
      if (e2 < dx) { err += dx; y0 += sy; }
    }
    return out;
  }

  function screenToCell(ev) {
    const rect = els.mapCanvas.getBoundingClientRect();
    const mx = ev.clientX - rect.left;
    const my = ev.clientY - rect.top;
    return [
      Math.floor((state.camX + mx / state.zoom) / 16),
      Math.floor((state.camY + my / state.zoom) / 16),
    ];
  }

  function setHover(ev) {
    const [x, y] = screenToCell(ev);
    state.hover = { x, y };
    updateStatus();
    renderInspector();
  }

  function removeObjectsAt(x, y) {
    const s = state.active;
    const before = s.data.objects.length;
    s.data.objects = s.data.objects.filter((o) => !(o.x === x && o.y === y));
    return s.data.objects.length !== before;
  }

  function placeObject(x, y) {
    const s = state.active;
    if (!state.selectedObject) return false;
    if (x < 0 || y < 0 || x >= s.data.width || y >= s.data.height) return false;
    const spec = state.selectedObject;
    if (spec.kind === C.KIND_TRIGGER && (spec.type === C.SPAWN || spec.type === C.EXIT)) {
      s.data.objects = s.data.objects.filter((o) => !(o.kind === C.KIND_TRIGGER && o.type === spec.type));
    }
    s.data.objects.push({
      kind: spec.kind, type: spec.type, x, y, flags: 0,
      param: spec.type === 4611 ? 1 : 0,
    });
    return true;
  }

  // ---------------------------------------------------------------------
  // Mouse interaction
  // ---------------------------------------------------------------------
  function bindCanvas() {
    const canvas = els.mapCanvas;
    canvas.tabIndex = 0;
    canvas.addEventListener('contextmenu', (e) => e.preventDefault());

    canvas.addEventListener('pointerdown', (e) => {
      canvas.focus();
      const [cx, cy] = screenToCell(e);
      state.hover = { x: cx, y: cy };
      if (e.button === 1 || (e.button === 0 && state.spaceDown)) {
        state.panning = true;
        state.panStart = {
          sx: e.clientX, sy: e.clientY, camX: state.camX, camY: state.camY,
        };
        canvas.setPointerCapture(e.pointerId);
        e.preventDefault();
        return;
      }
      if (e.button !== 0 && e.button !== 2) return;
      const s = state.active;
      if (!s) return;
      if (cx < 0 || cy < 0 || cx >= s.data.width || cy >= s.data.height) return;

      if (state.layer === 'anomalies') {
        focusAnomalyAt(cx, cy);
        return;
      }
      if (state.layer === 'objects') {
        const erase = e.button === 2 || state.tool === 'erase';
        let hit = -1;
        for (let i = 0; i < s.data.objects.length; i++) {
          const o = s.data.objects[i];
          if (o.x === cx && o.y === cy) hit = i;
        }
        if (!erase && hit >= 0) {
          state.selectedObj = hit;
          render(); renderInspector();
          return;
        }
        pushHistory();
        let changed;
        if (erase) {
          changed = removeObjectsAt(cx, cy);
          state.selectedObj = -1;
        } else {
          changed = placeObject(cx, cy);
          if (changed) state.selectedObj = s.data.objects.length - 1;
        }
        if (changed) markDirty();
        else s.history.pop();
        render(); renderInspector(); renderWarnings();
        return;
      }
      if (state.tool === 'picker') {
        picker(cx, cy);
        return;
      }
      const erase = e.button === 2 || state.tool === 'erase';
      pushHistory();
      if (state.tool === 'fill') {
        floodFill(cx, cy, erase);
        markDirty();
        state.painting = false;
      } else {
        applyAt(cx, cy, erase);
        markDirty();
        state.painting = true;
        state.lastPaint = { x: cx, y: cy, erase };
        canvas.setPointerCapture(e.pointerId);
      }
      render();
      renderInspector();
    });

    canvas.addEventListener('pointermove', (e) => {
      if (state.panning && state.panStart) {
        const p = state.panStart;
        state.camX = p.camX - (e.clientX - p.sx) / state.zoom;
        state.camY = p.camY - (e.clientY - p.sy) / state.zoom;
        if (state.active.cam) {
          state.active.cam.x = state.camX; state.active.cam.y = state.camY;
        }
        render();
        return;
      }
      if (state.painting && state.lastPaint) {
        const [cx, cy] = screenToCell(e);
        if (cx !== state.lastPaint.x || cy !== state.lastPaint.y) {
          const cells = lineCells(state.lastPaint.x, state.lastPaint.y, cx, cy);
          for (const [x, y] of cells) applyAt(x, y, state.lastPaint.erase);
          state.lastPaint.x = cx;
          state.lastPaint.y = cy;
          if (state.active.cam) { /* camera unchanged */ }
          state.hover = { x: cx, y: cy };
          updateStatus();
          render();
        }
        return;
      }
      setHover(e);
      render();
    });

    const endPaint = () => {
      if (state.panning) {
        state.panning = false;
        state.panStart = null;
      }
      if (state.painting) {
        state.painting = false;
        state.lastPaint = null;
        renderInspector();
        renderAnomalies();
        updateTabs();
      }
    };
    canvas.addEventListener('pointerup', endPaint);
    canvas.addEventListener('pointercancel', endPaint);
    canvas.addEventListener('pointerleave', () => {
      state.hover = null;
      updateStatus();
      render();
    });

    canvas.addEventListener('wheel', (e) => {
      e.preventDefault();
      const rect = canvas.getBoundingClientRect();
      const mx = e.clientX - rect.left;
      const my = e.clientY - rect.top;
      const worldX = state.camX + mx / state.zoom;
      const worldY = state.camY + my / state.zoom;
      const factor = e.deltaY < 0 ? 1.18 : 1 / 1.18;
      const zoom = clamp(state.zoom * factor, 0.5, 6);
      state.zoom = zoom;
      state.camX = worldX - mx / zoom;
      state.camY = worldY - my / zoom;
      if (state.active.cam) {
        state.active.cam.zoom = zoom;
        state.active.cam.x = state.camX;
        state.active.cam.y = state.camY;
      }
      els.statusZoom.textContent = 'zoom ' + Math.round(zoom * 100) / 100 + 'x';
      render();
    }, { passive: false });

    new ResizeObserver(resizeCanvas).observe(els.viewport);
  }

  function picker(cx, cy) {
    const s = state.active;
    if (!s) return;
    const idx = cy * s.data.width + cx;
    if (state.layer === 'collision') {
      state.collisionBrush = s.data.collision[idx];
      els.collisionBrush.value = String(state.collisionBrush);
    } else {
      state.selectedTile = s.data.terrain[idx];
      renderPalette();
    }
    toast(`Picked ${state.selectedTile} / collision ${state.collisionBrush}`);
    renderInspector();
  }

  function focusAnomaly(index) {
    const s = state.active;
    if (!s || !s.anomalies[index]) return;
    s.selectedAnomaly = index;
    state.selectedAnomaly = index;
    const a = s.anomalies[index];
    const cw = els.mapCanvas.clientWidth, ch = els.mapCanvas.clientHeight;
    const tx = (a.x + (a.w || 1) / 2) * 16;
    const ty = (a.y + (a.h || 1) / 2) * 16;
    state.camX = tx - cw / (2 * state.zoom);
    state.camY = ty - ch / (2 * state.zoom);
    if (s.cam) { s.cam.x = state.camX; s.cam.y = state.camY; }
    render();
    renderAnomalies();
  }

  function focusAnomalyAt(cx, cy) {
    const s = state.active;
    const idx = s.anomalies.findIndex((a) =>
      cx >= a.x && cy >= a.y && cx < a.x + (a.w || 1) && cy < a.y + (a.h || 1));
    if (idx >= 0) focusAnomaly(idx);
    else toast('No anomaly at this cell');
  }

  // ---------------------------------------------------------------------
  // Anomaly actions
  // ---------------------------------------------------------------------
  function acceptAnomaly(index) {
    const s = state.active;
    const a = s.anomalies[index];
    if (!a) return;
    pushHistory();
    restoreAnomalyTerrain(s, a);
    const defaultType = a.suggestion === 'item' ? C.ITEM_BASE : C.ENEMY_BASE;
    const kind = a.suggestion === 'item' ? C.KIND_ITEM : C.KIND_ENEMY;
    const existing = s.data.objects.find((o) =>
      o.kind === kind && o.x === a.x && o.y === a.y);
    if (existing) existing.flags &= ~C.LOCKED;
    else {
      s.data.objects.push({
        kind, type: defaultType, x: a.x, y: a.y, flags: 0, param: kind === C.KIND_ITEM ? 1 : 0,
      });
    }
    s.anomalies.splice(index, 1);
    s.selectedAnomaly = -1;
    state.selectedAnomaly = -1;
    pruneTempWarnings(s);
    markDirty();
    render(); renderAnomalies(); renderInspector(); renderWarnings();
  }

  function dismissAnomaly(index) {
    const s = state.active;
    if (!s.anomalies[index]) return;
    pushHistory();
    restoreAnomalyTerrain(s, s.anomalies[index]);
    s.anomalies.splice(index, 1);
    s.selectedAnomaly = -1;
    state.selectedAnomaly = -1;
    pruneTempWarnings(s);
    markDirty();
    render(); renderAnomalies(); renderInspector(); renderWarnings();
  }

  function acceptAllAnomalies() {
    const s = state.active;
    if (!s || !s.anomalies.length) return;
    pushHistory();
    for (const a of s.anomalies) {
      restoreAnomalyTerrain(s, a);
      const kind = a.suggestion === 'item' ? C.KIND_ITEM : C.KIND_ENEMY;
      const type = a.suggestion === 'item' ? C.ITEM_BASE : C.ENEMY_BASE;
      let existing = s.data.objects.find((o) => o.kind === kind && o.x === a.x && o.y === a.y);
      if (existing) existing.flags &= ~C.LOCKED;
      else s.data.objects.push({ kind, type, x: a.x, y: a.y, flags: 0, param: kind === C.KIND_ITEM ? 1 : 0 });
    }
    s.anomalies = [];
    s.selectedAnomaly = -1;
    state.selectedAnomaly = -1;
    pruneTempWarnings(s);
    markDirty();
    render(); renderAnomalies(); renderInspector(); renderWarnings();
    toast('All anomalies accepted');
  }

  // ---------------------------------------------------------------------
  // Re-slice / tile creation
  // ---------------------------------------------------------------------
  function ensureAtlasCapacity(id) {
    const columns = state.manifest.columns || 64;
    const size = state.manifest.tileSize || 16;
    const needRows = Math.floor(id / columns) + 1;
    const needHeight = needRows * size;
    if (state.atlasCanvas.height >= needHeight) return;
    const next = document.createElement('canvas');
    next.width = columns * size;
    next.height = needHeight;
    const ctx = next.getContext('2d');
    ctx.imageSmoothingEnabled = false;
    ctx.drawImage(state.atlasCanvas, 0, 0);
    state.atlasCanvas = next;
    state.atlasCtx = ctx;
    state.manifest.height = needHeight;
    state.manifest.rows = needRows;
  }

  function addTileFromCell(rgba, rgbForHash) {
    let max = 0;
    if (rgbForHash.every((v) => v <= 6)) return 0;
    const hash = fnv1a(rgbForHash);
    const existing = state.hashToId.get(hash);
    if (existing != null) return existing;
    const id = state.nextTileId++;
    if (id > C.TILE_MAX) throw new Error('terrain tile id range exhausted');
    const columns = state.manifest.columns || 64;
    const size = state.manifest.tileSize || 16;
    ensureAtlasCapacity(id);
    const imgData = new ImageData(new Uint8ClampedArray(rgba), size, size);
    state.atlasCtx.putImageData(imgData, (id % columns) * size, Math.floor(id / columns) * size);
    const meta = {
      id, hash, fastHash: hash, atlasIndex: id,
      sx: (id % columns) * size, sy: Math.floor(id / columns) * size,
      name: 'unknown_' + id, kind: 'unknown', collision: 0,
      shared: false, maps: {}, count: 1,
    };
    state.manifest.tiles.push(meta);
    state.manifest.tileCount = (state.manifest.tileCount || 0) + 1;
    state.tileMeta[id] = meta;
    state.hashToId.set(hash, id);
    return id;
  }

  function resliceCurrent() {
    const s = state.active;
    if (!s) return;
    const img = state.sources[s.sourceKey];
    if (!img) { toast('No source screenshot for this map.', true); return; }
    const ox = clamp(parseInt(els.offsetX.value, 10) || 0, 0, 255);
    const oy = clamp(parseInt(els.offsetY.value, 10) || 0, 0, 255);
    if (!confirm(`Re-cut ${s.name} from the screenshot at offset ${ox},${oy}? Current terrain will be replaced; objects are kept.`)) return;
    try {
      const off = document.createElement('canvas');
      off.width = img.width; off.height = img.height;
      const octx = off.getContext('2d', { willReadFrequently: true });
      octx.drawImage(img, 0, 0);
      const imageData = octx.getImageData(0, 0, img.width, img.height);
      const width = Math.max(1, Math.ceil((img.width - ox) / 16));
      const height = Math.max(1, Math.ceil((img.height - oy) / 16));
      const terrain = new Uint16Array(width * height);
      const collision = new Uint8Array(width * height);
      const rgba = new Uint8Array(16 * 16 * 4);
      const rgb = new Uint8Array(16 * 16 * 3);
      for (let cy = 0; cy < height; cy++) {
        for (let cx = 0; cx < width; cx++) {
          rgba.fill(0); rgb.fill(0);
          for (let y = 0; y < 16; y++) {
            const sy = oy + cy * 16 + y;
            for (let x = 0; x < 16; x++) {
              const sx = ox + cx * 16 + x;
              const o = (y * 16 + x);
              if (sx >= 0 && sy >= 0 && sx < img.width && sy < img.height) {
                const si = (sy * img.width + sx) * 4;
                rgba[o * 4] = imageData.data[si];
                rgba[o * 4 + 1] = imageData.data[si + 1];
                rgba[o * 4 + 2] = imageData.data[si + 2];
                rgba[o * 4 + 3] = 255;
                rgb[o * 3] = imageData.data[si];
                rgb[o * 3 + 1] = imageData.data[si + 1];
                rgb[o * 3 + 2] = imageData.data[si + 2];
              }
            }
          }
          const id = addTileFromCell(rgba, rgb);
          const idx = cy * width + cx;
          terrain[idx] = id;
          const meta = state.tileMeta[id];
          collision[idx] = meta ? (meta.collision || 0) : 0;
        }
      }
      pushHistory();
      s.data.width = width;
      s.data.height = height;
      s.data.terrain = terrain;
      s.data.collision = collision;
      s.data.objects = s.data.objects.filter((o) => o.x < width && o.y < height);
      s.offset = [ox, oy];
      s.anomalies = [];
      s.selectedAnomaly = -1;
      state.selectedAnomaly = -1;
      s.warnings.push(`terrain re-sliced from ${s.sourceKey} at offset ${ox},${oy}`);
      markDirty();
      fitView();
      renderPalette(); renderAnomalies(); renderWarnings(); renderInspector(); render(); updateTabs();
      toast(`Re-sliced ${width}x${height} cells`);
    } catch (err) {
      toast('Re-slice failed: ' + err.message, true);
    }
  }

  // ---------------------------------------------------------------------
  // Import / export
  // ---------------------------------------------------------------------
  function download(blob, filename) {
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 2000);
  }

  function downloadMap() {
    const s = state.active;
    if (!s) return;
    try {
      const bytes = encodeJMap(s.data);
      download(new Blob([bytes], { type: 'application/octet-stream' }), s.name + '.jmap');
      toast(`Exported ${s.name}.jmap (${bytes.length} bytes)`);
    } catch (e) { toast('Export failed: ' + e.message, true); }
  }

  function renderFullMap(s) {
    const canvas = document.createElement('canvas');
    canvas.width = s.data.width * 16;
    canvas.height = s.data.height * 16;
    const ctx = canvas.getContext('2d');
    ctx.imageSmoothingEnabled = false;
    ctx.fillStyle = '#000';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    const columns = state.manifest.columns || 64;
    for (let cy = 0; cy < s.data.height; cy++) {
      for (let cx = 0; cx < s.data.width; cx++) {
        const id = s.data.terrain[cy * s.data.width + cx];
        if (!id) continue;
        const sx = (id % columns) * 16;
        const sy = Math.floor(id / columns) * 16;
        if (sx + 16 > state.atlasCanvas.width || sy + 16 > state.atlasCanvas.height) continue;
        ctx.drawImage(state.atlasCanvas, sx, sy, 16, 16, cx * 16, cy * 16, 16, 16);
      }
    }
    for (const obj of s.data.objects) drawObject(ctx, obj, 0, 0, 1);
    return canvas;
  }

  function preRender() {
    const s = state.active;
    if (!s) return;
    if (s.anomalies.length) {
      if (!confirm(`There are ${s.anomalies.length} unresolved anomalies. Render anyway?`)) return;
    }
    const canvas = renderFullMap(s);
    canvas.toBlob((blob) => {
      if (blob) download(blob, s.name + '_preview.png');
      toast(`Rendered ${canvas.width}x${canvas.height} PNG`);
    }, 'image/png');
  }

  function exportProject() {
    const project = JSON.parse(JSON.stringify(state.project || {}));
    project.maps = state.mapOrder.map((name) => {
      const s = state.maps[name];
      const base = s.project || {};
      return {
        ...base,
        name,
        offset: s.offset,
        width: s.data.width,
        height: s.data.height,
        anomalies: s.anomalies,
        warnings: s.warnings,
        objects: s.data.objects,
        tileSize: s.data.tileSize,
      };
    });
    project.exportedAt = new Date().toISOString();
    const blob = new Blob([JSON.stringify(project, null, 2)], { type: 'application/json' });
    download(blob, 'project.json');
    toast('Exported project.json');
  }

  function cleanGarbage() {
    if (!state.manifest) return;
    const used = new Set();
    for (const name of state.mapOrder) {
      const map = state.maps[name];
      for (const id of map.data.terrain) used.add(id);
      for (const a of map.anomalies) {
        for (const fix of (a.fixTiles || [])) used.add(fix[2]);
      }
    }
    const columns = state.manifest.columns || 64;
    const size = state.manifest.tileSize || 16;
    const removed = [];
    for (const key of Object.keys(state.tileMeta)) {
      const id = Number(key);
      if (id === C.EMPTY || used.has(id)) continue;
      const meta = state.tileMeta[id];
      removed.push(id);
      delete state.tileMeta[id];
      if (meta.fastHash) state.hashToId.delete(meta.fastHash);
      if (meta.hash) state.hashToId.delete(meta.hash);
      if (state.atlasCtx) {
        const sx = (id % columns) * size;
        const sy = Math.floor(id / columns) * size;
        state.atlasCtx.fillStyle = '#000';
        state.atlasCtx.fillRect(sx, sy, size, size);
      }
    }
    if (!removed.length) {
      toast('No unused or broken tiles to clean');
      return;
    }
    state.manifest.tiles = Object.values(state.tileMeta)
      .filter((t) => t.id !== C.EMPTY)
      .sort((a, b) => a.id - b.id);
    state.manifest.tileCount = state.manifest.tiles.length + 1;
    for (const name of state.mapOrder) pruneTempWarnings(state.maps[name]);
    if (!state.tileMeta[state.selectedTile]) state.selectedTile = 1;
    renderPalette();
    renderInspector();
    renderAnomalies();
    renderWarnings();
    render();
    toast(`Cleaned ${removed.length} unused/broken tile(s)`);
  }

  function exportTileset() {
    if (!state.manifest) return;
    const manifest = JSON.parse(JSON.stringify(state.manifest));
    manifest.tiles = Object.values(state.tileMeta)
      .filter((t) => t.id !== 0)
      .sort((a, b) => a.id - b.id)
      .map((t) => ({
        ...t,
        shared: !t.temp && !!(t.maps && Object.keys(t.maps).length >= 2),
        count: t.maps ? Object.values(t.maps).reduce((a, b) => a + b, 0) : t.count,
      }));
    manifest.tileCount = manifest.tiles.length + 1;
    download(new Blob([JSON.stringify(manifest, null, 2)], { type: 'application/json' }), 'tileset.json');
    state.atlasCanvas.toBlob((blob) => {
      if (blob) download(blob, 'tileset.png');
    }, 'image/png');
    toast('Exported tileset.json + tileset.png');
  }

  async function importMapFile(file) {
    const bytes = new Uint8Array(await file.arrayBuffer());
    const data = decodeJMap(bytes);
    let name = data.name || file.name.replace(/\.jmap$/i, '');
    let base = name, n = 2;
    while (state.maps[name]) name = `${base}_${n++}`;
    data.name = name;
    const s = {
      name, data, project: { name }, anomalies: [], warnings: [],
      offset: [0, 0], sourceKey: null, sourcePath: null,
      history: [], redo: [], dirty: true, selectedAnomaly: -1, cam: null,
    };
    state.maps[name] = s;
    state.mapOrder.push(name);
    selectMap(name);
    fitView();
    markDirty();
    render();
    toast('Imported ' + name);
  }

  async function importTilesetFiles(files) {
    const jsonFile = files.find((f) => f.name.toLowerCase().endsWith('.json'));
    const pngFile = files.find((f) => /\.png$/i.test(f.name));
    if (!jsonFile || !pngFile) { toast('Select tileset.json and tileset.png together.', true); return; }
    const manifest = JSON.parse(await jsonFile.text());
    const image = await loadImage(URL.createObjectURL(pngFile));
    state.manifest = manifest;
    state.manifest.tileSize = state.manifest.tileSize || 16;
    state.manifest.columns = state.manifest.columns || 64;
    buildAtlasCanvas(image);
    indexTiles();
    // Fill in a fast hash for older manifests that only carry SHA-1.
    for (const tile of state.manifest.tiles) {
      if (tile.fastHash) continue;
      const columns = state.manifest.columns, size = state.manifest.tileSize;
      const sx = (tile.id % columns) * size, sy = Math.floor(tile.id / columns) * size;
      const data = state.atlasCtx.getImageData(sx, sy, size, size).data;
      const rgb = new Uint8Array(size * size * 3);
      for (let i = 0; i < size * size; i++) {
        rgb[i * 3] = data[i * 4]; rgb[i * 3 + 1] = data[i * 4 + 1]; rgb[i * 3 + 2] = data[i * 4 + 2];
      }
      tile.fastHash = fnv1a(rgb);
      state.hashToId.set(tile.fastHash, tile.id);
    }
    renderPalette(); renderObjectPalette(); render();
    toast('Tileset loaded: ' + state.manifest.tiles.length + ' tiles');
  }

  async function replaceSource(file) {
    const s = state.active;
    if (!s) return;
    const img = await loadImage(URL.createObjectURL(file));
    s.sourceKey = 'custom_' + s.name;
    state.sources[s.sourceKey] = img;
    state.showSource = true;
    els.toggleSource.checked = true;
    render();
    toast('Screenshot replaced. Set the grid offset and press Re-slice.');
  }

  // ---------------------------------------------------------------------
  // Event wiring
  // ---------------------------------------------------------------------
  function toast(message, error = false) {
    els.toast.textContent = message;
    els.toast.className = 'toast' + (error ? ' error' : '');
    clearTimeout(toast._timer);
    toast._timer = setTimeout(() => els.toast.classList.add('hidden'), 3200);
  }

  function bindUI() {
    els.mapTabs.addEventListener('click', (e) => {
      const btn = e.target.closest('button[data-map]');
      if (btn) selectMap(btn.dataset.map);
    });

    els.layerButtons.addEventListener('click', (e) => {
      const btn = e.target.closest('button[data-layer]');
      if (!btn) return;
      state.layer = btn.dataset.layer;
      [...els.layerButtons.children].forEach((b) => b.classList.toggle('active', b === btn));
      els.collisionTools.classList.toggle('hidden', state.layer !== 'collision');
      renderPalette();
      render();
    });

    els.toolButtons.addEventListener('click', (e) => {
      const btn = e.target.closest('button[data-tool]');
      if (!btn) return;
      state.tool = btn.dataset.tool;
      [...els.toolButtons.children].forEach((b) => b.classList.toggle('active', b === btn));
    });

    els.paletteFilters.addEventListener('click', (e) => {
      const btn = e.target.closest('button[data-filter]');
      if (!btn) return;
      state.paletteFilter = btn.dataset.filter;
      [...els.paletteFilters.children].forEach((b) => b.classList.toggle('active', b === btn));
      renderPalette();
    });

    els.paletteSearch.addEventListener('input', () => {
      state.paletteSearch = els.paletteSearch.value;
      renderPalette();
    });

    els.paletteCanvas.addEventListener('click', (e) => {
      const item = hitPalette(e);
      if (!item) return;
      state.selectedTile = item.id;
      if (state.layer === 'collision') state.layer = 'terrain';
      renderPalette();
      renderInspector();
      render();
    });

    els.collisionBrush.addEventListener('change', () => {
      state.collisionBrush = parseInt(els.collisionBrush.value, 10) || 0;
    });

    els.toggleGrid.addEventListener('change', () => { state.showGrid = els.toggleGrid.checked; render(); });
    els.toggleObjects.addEventListener('change', () => { state.showObjects = els.toggleObjects.checked; render(); });
    els.toggleCollision.addEventListener('change', () => { state.showCollision = els.toggleCollision.checked; render(); });
    els.toggleAnomalies.addEventListener('change', () => { state.showAnomalies = els.toggleAnomalies.checked; render(); });
    els.toggleSource.addEventListener('change', () => { state.showSource = els.toggleSource.checked; render(); });

    els.objectTabs.addEventListener('click', (e) => {
      const btn = e.target.closest('button[data-objects]');
      if (!btn) return;
      state.objectFilter = btn.dataset.objects;
      [...els.objectTabs.children].forEach((b) => b.classList.toggle('active', b === btn));
      state.selectedObject = null;
      renderObjectPalette();
    });

    els.objectList.addEventListener('click', (e) => {
      const item = e.target.closest('.object-item');
      if (!item) return;
      state.selectedObject = {
        kind: parseInt(item.dataset.kind, 10),
        type: parseInt(item.dataset.type, 10),
      };
      state.layer = 'objects';
      [...els.layerButtons.children].forEach((b) =>
        b.classList.toggle('active', b.dataset.layer === 'objects'));
      els.collisionTools.classList.add('hidden');
      renderObjectPalette();
      renderInspector();
      renderPalette();
      render();
    });

    els.inspector.addEventListener('change', (e) => {
      const s = state.active;
      if (!s || state.selectedObj < 0 || state.selectedObj >= s.data.objects.length) return;
      const o = s.data.objects[state.selectedObj];
      const field = e.target.id;
      if (!['objType', 'objX', 'objY', 'objParam', 'objFlags'].includes(field)) return;
      pushHistory();
      if (field === 'objType') o.type = clamp(parseInt(e.target.value, 10) || 0, 0, 65535);
      else if (field === 'objX') o.x = clamp(parseInt(e.target.value, 10) || 0, 0, s.data.width - 1);
      else if (field === 'objY') o.y = clamp(parseInt(e.target.value, 10) || 0, 0, s.data.height - 1);
      else if (field === 'objParam') o.param = clamp(parseInt(e.target.value, 10) || 0, 0, 65535);
      else if (field === 'objFlags') o.flags = clamp(parseInt(e.target.value, 10) || 0, 0, 255);
      markDirty();
      render(); renderInspector(); renderWarnings();
    });

    els.inspector.addEventListener('click', (e) => {
      const s = state.active;
      if (!s || e.target.id !== 'objDelete' || state.selectedObj < 0) return;
      pushHistory();
      s.data.objects.splice(state.selectedObj, 1);
      state.selectedObj = -1;
      markDirty();
      render(); renderInspector(); renderWarnings();
    });

    els.anomalyList.addEventListener('click', (e) => {
      const btn = e.target.closest('button[data-act]');
      if (btn) {
        const index = parseInt(btn.dataset.index, 10);
        if (btn.dataset.act === 'focus') focusAnomaly(index);
        else if (btn.dataset.act === 'accept') acceptAnomaly(index);
        else if (btn.dataset.act === 'dismiss') dismissAnomaly(index);
        return;
      }
      const card = e.target.closest('[data-anomaly]');
      if (card) focusAnomaly(parseInt(card.dataset.anomaly, 10));
    });

    els.btnAcceptAll.addEventListener('click', acceptAllAnomalies);
    els.btnNextAnomaly.addEventListener('click', () => {
      const s = state.active;
      if (!s || !s.anomalies.length) { toast('No anomalies left'); return; }
      const next = (s.selectedAnomaly + 1) % s.anomalies.length;
      focusAnomaly(next);
    });

    els.btnRender.addEventListener('click', preRender);
    els.btnExportMap.addEventListener('click', downloadMap);
    els.btnExportProject.addEventListener('click', exportProject);
    els.btnExportTileset.addEventListener('click', exportTileset);
    els.btnCleanGarbage.addEventListener('click', cleanGarbage);
    els.btnReslice.addEventListener('click', resliceCurrent);

    els.btnImportMap.addEventListener('click', () => els.fileMap.click());
    els.btnImportTileset.addEventListener('click', () => els.fileTileset.click());
    els.btnReplaceSource.addEventListener('click', () => els.fileSource.click());

    els.fileMap.addEventListener('change', async () => {
      const file = els.fileMap.files[0];
      els.fileMap.value = '';
      if (!file) return;
      try { await importMapFile(file); } catch (e) { toast('Import failed: ' + e.message, true); }
    });
    els.fileTileset.addEventListener('change', async () => {
      const files = [...els.fileTileset.files];
      els.fileTileset.value = '';
      if (files.length) {
        try { await importTilesetFiles(files); } catch (e) { toast('Tileset import failed: ' + e.message, true); }
      }
    });
    els.fileSource.addEventListener('change', async () => {
      const file = els.fileSource.files[0];
      els.fileSource.value = '';
      if (file) {
        try { await replaceSource(file); } catch (e) { toast('Image load failed', true); }
      }
    });

    document.addEventListener('keydown', (e) => {
      const tag = (e.target.tagName || '').toLowerCase();
      if (tag === 'input' || tag === 'select' || tag === 'textarea') return;
      if (e.code === 'Space') {
        state.spaceDown = true;
        e.preventDefault();
        return;
      }
      if (e.ctrlKey || e.metaKey) {
        if (e.key.toLowerCase() === 'z') { e.preventDefault(); undo(); }
        else if (e.key.toLowerCase() === 'y') { e.preventDefault(); redo(); }
        else if (e.key.toLowerCase() === 's') { e.preventDefault(); downloadMap(); }
        return;
      }
      const key = e.key.toLowerCase();
      if (key === '1') setLayer('terrain');
      else if (key === '2') setLayer('collision');
      else if (key === '3') setLayer('objects');
      else if (key === '4') setLayer('anomalies');
      else if (key === 'b') setTool('brush');
      else if (key === 'e') setTool('erase');
      else if (key === 'f') setTool('fill');
      else if (key === 'i') setTool('picker');
      else if (key === 'g') { state.showGrid = !state.showGrid; els.toggleGrid.checked = state.showGrid; render(); }
      else if (key === 'delete' || key === 'backspace') {
        if (state.hover && state.active) {
          pushHistory();
          if (removeObjectsAt(state.hover.x, state.hover.y)) { markDirty(); render(); }
          else state.active.history.pop();
        }
      }
      else if (key === 'escape') {
        if (state.active) { state.active.selectedAnomaly = -1; state.selectedAnomaly = -1; renderAnomalies(); render(); }
      }
    });
    document.addEventListener('keyup', (e) => {
      if (e.code === 'Space') state.spaceDown = false;
    });

    document.addEventListener('wheel', (e) => {
      if (e.ctrlKey) e.preventDefault();
    }, { passive: false });
  }

  function setLayer(layer) {
    const btn = [...els.layerButtons.children].find((b) => b.dataset.layer === layer);
    if (btn) btn.click();
  }
  function setTool(tool) {
    const btn = [...els.toolButtons.children].find((b) => b.dataset.tool === tool);
    if (btn) btn.click();
  }

  // ---------------------------------------------------------------------
  // Boot
  // ---------------------------------------------------------------------
  let bootStarted = false;
  async function boot() {
    if (bootStarted) return;
    bootStarted = true;
    bindCanvas();
    bindUI();
    resizeCanvas();
    const bundle = window.ALONEHORROR_BUNDLE;
    if (!bundle) {
      els.emptyState.classList.remove('hidden');
      els.statusMap.textContent = 'no map loaded';
      return;
    }
    try {
      await initBundle(bundle);
      resizeCanvas();
      render();
      toast('Loaded ' + state.mapOrder.length + ' maps');
    } catch (e) {
      console.error(e);
      els.emptyState.classList.remove('hidden');
      toast('Bundle failed: ' + e.message, true);
    }
  }

  // A tiny read-only-ish debug surface used by editor/selftest.html and by
  // power users from the browser console.  It is intentionally not linked in
  // the UI.
  window.__AH__ = {
    state,
    api: {
      encodeJMap,
      decodeJMap,
      fnv1a,
      base64ToBytes,
      selectMap,
      acceptAllAnomalies,
      cleanGarbage,
      renderFullMap,
      boot,
      activeStats() {
        const s = state.active;
        if (!s) return null;
        const bytes = encodeJMap(s.data);
        let nonBlack = 0;
        const canvas = renderFullMap(s);
        const data = canvas.getContext('2d').getImageData(0, 0, canvas.width, canvas.height).data;
        for (let i = 0; i < data.length; i += 4) {
          if (data[i] || data[i + 1] || data[i + 2]) nonBlack++;
        }
        let b64 = '';
        const chunk = 0x8000;
        for (let i = 0; i < bytes.length; i += chunk) {
          b64 += String.fromCharCode.apply(null, bytes.subarray(i, i + chunk));
        }
        return {
          name: s.name, width: s.data.width, height: s.data.height,
          objects: s.data.objects.length, anomalies: s.anomalies.length,
          terrain: s.data.terrain.length, bytes: bytes.length,
          base64: btoa(b64), nonBlack,
        };
      },
    },
  };

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', boot);
  } else {
    boot();
  }
})();
